-- Run in the Supabase SQL editor. Requires the pgvector extension.
create extension if not exists vector with schema extensions;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz default now());
create table if not exists public.subjects (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, attended int not null default 0 check(attended>=0), total_classes int not null default 0 check(total_classes>=attended), target numeric not null default 75 check(target>0 and target<=100), created_at timestamptz default now());
create table if not exists public.assessments (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid references public.subjects(id) on delete cascade, title text not null, score numeric not null check(score>=0), max_score numeric not null check(max_score>0 and score<=max_score), assessed_on date, created_at timestamptz default now());
create table if not exists public.assignments (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid references public.subjects(id) on delete set null, title text not null, due_date date, completed boolean not null default false, created_at timestamptz default now());
create table if not exists public.study_tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid references public.subjects(id) on delete set null, title text not null, due_date date, duration_minutes int, priority text default 'medium', completed boolean default false, created_at timestamptz default now());
create table if not exists public.documents (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, status text not null default 'ready', created_at timestamptz default now());
create table if not exists public.document_chunks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, document_id uuid not null references public.documents(id) on delete cascade, chunk_index int not null, content text not null, embedding extensions.vector(768), created_at timestamptz default now());
-- The MVP server stores a validated workspace snapshot here, scoped to the verified Auth user.
create table if not exists public.student_workspaces (user_id uuid primary key references auth.users(id) on delete cascade, data jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create index if not exists document_chunks_user_doc_idx on public.document_chunks(user_id,document_id);
create index if not exists document_chunks_embedding_idx on public.document_chunks using hnsw (embedding extensions.vector_cosine_ops);
alter table public.profiles enable row level security;
alter table public.subjects enable row level security;
alter table public.assessments enable row level security;
alter table public.assignments enable row level security;
alter table public.study_tasks enable row level security;
alter table public.documents enable row level security;
alter table public.document_chunks enable row level security;
drop policy if exists "Users manage own profile" on public.profiles;
create policy "Users manage own profile" on public.profiles for all to authenticated using ((select auth.uid())=id) with check((select auth.uid())=id);
drop policy if exists "Users manage own subjects" on public.subjects;
create policy "Users manage own subjects" on public.subjects for all to authenticated using ((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "Users manage own assessments" on public.assessments;
create policy "Users manage own assessments" on public.assessments for all to authenticated using ((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "Users manage own assignments" on public.assignments;
create policy "Users manage own assignments" on public.assignments for all to authenticated using ((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "Users manage own tasks" on public.study_tasks;
create policy "Users manage own tasks" on public.study_tasks for all to authenticated using ((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "Users manage own documents" on public.documents;
create policy "Users manage own documents" on public.documents for all to authenticated using ((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "Users manage own chunks" on public.document_chunks;
create policy "Users manage own chunks" on public.document_chunks for all to authenticated using ((select auth.uid())=user_id) with check((select auth.uid())=user_id);
alter table public.student_workspaces enable row level security;
revoke all on public.student_workspaces from anon;
grant select, insert, update on public.student_workspaces to authenticated;
drop policy if exists "Users manage own workspace" on public.student_workspaces;
create policy "Users manage own workspace" on public.student_workspaces for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
